let probeFixtureKey = new URLSearchParams(location.search).get('probe-fixture');
// UI contract fixtures for the cutoff pair view, derived by src/review/pairing.py and
// labelled synthetic; `?pair-fixture=<key>` previews one. See docs/work/reviews/UI-2.md.
let pairFixtureKey = new URLSearchParams(location.search).get('pair-fixture');
let pairOptions = [], pairTaskCount = 0;
const PROBE_QIDS = ['q1','q2','q3','q4','q5','q6','q7','q8'];
