  node('p', `${raw(metadata.execution_mode)} · ${metadata.model_version || 'unknown version'} · ${metadata.bundle_version || 'unknown bundle'}`, box).className = 'probe-meta';
  node('p', String(composed.label || 'unknown').toUpperCase(), box).className = 'probe-label';
  node('p', `Fired rule: ${composed.fired_rule || '—'}`, box).className = 'probe-answer';
  if (composed.reason) node('p', `Reason: ${composed.reason}`, box);
  const escalation = String(composed.escalation || 'none');
  const line = node('p', escalation === 'none' ? 'Escalation: none' : `Escalation: ${escalation.replaceAll('_', ' ')}`, box);
  if (escalation !== 'none') line.className = 'probe-alert';
  const unstable = receipt.unstable === true;
  const flips = node('p', unstable
    ? `Instability: UNSTABLE — ${(receipt.unstable_questions || []).map(qid=>qid.toUpperCase()).join(', ')} above tau_flip or tau_pol. The label is downgraded to insufficient and escalated.`
    : 'Instability: stable — no question exceeded tau_flip or tau_pol.', box);
