    node('h4', `${qid.toUpperCase()} ${unwrap(meta.slug)} · ${unwrap(meta.type)}`, atom);
    node('p', `Modal answer: ${unwrap((composed.atomic || {})[qid])}`, atom).className = 'probe-answer';
    const forms = [];
