  node('h3', 'Bundle metadata', box);
  node('p', `${metadata.provider || '—'} · ${metadata.model || '—'} · probabilities ${unwrap(metadata.probabilities)} · review state ${unwrap(payload.review_state)}${payload.synthetic ? ' · synthetic' : ''}`, box).className = 'probe-meta';
  node('p', `Request digest ${metadata.request_digest || '—'}`, box).className = 'probe-meta';
  node('p', `Output digest ${metadata.output_digest || '—'}`, box).className = 'probe-meta';
  const indices = new Set();
  for (const question of Object.values(payload.questions || {})) for (const index of question?.criteria?.passages || []) indices.add(index);
  const referenced = [...indices].sort((a, b) => a - b).filter(index => context && context[index]);
