function renderPairRefusal(box, error) {
  const code = (error && error.code) || 'PAIR_REFUSED';
  const line = node('p', '', box); line.className = 'pair-alert';
  node('strong', `${code} · `, line);
  line.append(document.createTextNode(PAIR_MESSAGES[code] || (error && error.message) || 'the service refused the pair'));
  const hint = PAIR_HINTS[code];
  node('p', hint ? `Nothing was saved and no accepted value changed. ${hint}` : 'Nothing was saved and no accepted value changed.', box).className = 'hint';
}
const renderPairNotice = (box, text) => { node('p', text, box).className = 'hint'; };
function renderPairForTask() {
  if (pairFixtureKey) { renderPairPreview(); return; }
  $('pair-badge').className = 'badge';
  if (!state) {
    pairOptions = []; pairTaskCount = 0;
    $('pair').replaceChildren(); $('pair-badge').textContent = 'NOT CONNECTED';
    $('pair-status').textContent = 'Cutoff pair availability is checked on connection.';
    controls(); return;
  }
  const box = renderPairPanel(state, $('assumption').value, null);
  // The words follow the candidate count, the same fact the compare control is gated by:
  // a pair of saved bundles needs no backend (`src/review/pairing.py` says the route
  // needs none), so a disconnected probe backend cannot make an available pair
  // unshowable. It only stops a new bundle being requested.
  const disconnected = state.bundle_available !== true;
  const cannotRequest = disconnected ? ' Probes are not connected, so a new bundle cannot be requested right now.' : '';
  if (pairOptions.length > 1) {
    $('pair-badge').textContent = 'DERIVED';
    $('pair-status').textContent = 'Two saved bundles for this assumption can be paired. The view is derived from the saved artifacts and stored nowhere.';
    renderPairNotice(box, 'Choose the earlier and the later bundle, then compare the two cutoffs. The comparison writes nothing and changes no accepted value.');
  } else {
    $('pair-badge').textContent = disconnected ? 'NOT CONNECTED' : 'DERIVED';
    if (pairTaskCount < 2) {
      $('pair-status').textContent = pairTaskCount === 1
        ? 'Only one compiled review exists for this assumption, so there is no pair to show.'
        : 'No compiled review exists for this assumption yet, so there is no pair to show.';
      renderPairNotice(box, 'A pair needs two compiled reviews of this assumption sharing one snapshot with a later information cutoff, each with a saved probe bundle. Prepare a second review with a later cutoff, then request its bundle.' + cannotRequest);
    } else {
      $('pair-status').textContent = `${pairTaskCount} compiled reviews for this assumption, ${pairOptions.length} with a saved probe bundle.`;
      renderPairNotice(box, 'Two saved probe bundles are needed before the two cutoffs can be compared. Request a bundle for the other review.' + cannotRequest);
    }
  }
  controls();
}
function renderPairPreview() {
  const source = pairSource();
  $('pair-badge').className = 'badge'; $('pair-badge').textContent = 'SYNTHETIC FIXTURE';
  if (!source) {
    pairOptions = []; pairTaskCount = 0; $('pair').replaceChildren();
    node('p', 'The UI contract fixture is unavailable.', $('pair'));
    $('pair-status').textContent = 'No UI contract fixture is available.';
    controls(); return;
  }
  const box = renderPairPanel(source, pairAssumptionOf(source), `UI CONTRACT FIXTURE · ${source.label} · ${source.note}`);
  if (source.error) {
    $('pair-status').textContent = 'The fixture carries a typed refusal the repository pairing function returned. No backend was called.';
    renderPairRefusal(box, source.error);
  } else if (source.view) {
    $('pair-status').textContent = 'The fixture carries a view the repository pairing function derived from two saved bundles. No backend was called and no case record was read.';
    renderPairView(box, source.view, source);
  } else {
    $('pair-status').textContent = `The fixture carries ${pairTaskCount} compiled review(s) and ${pairOptions.length} saved bundle(s), so there is no pair to show.`;
    renderPairNotice(box, 'A pair needs two compiled reviews of this assumption with a saved probe bundle each. The compare control stays disabled.');
  }
  controls();
}

// UI contract fixtures for the probe view (synthetic). Generated with the real S1
// functions in src/judgment/bundle.py from working-paper appendix A and the intent's
