const PAIR_FIXTURES = JSON.parse(PAIR_FIXTURE_JSON);
async function refresh() {
  state = await api('/workspace');
  const selected = $('assumption').value;
  $('assumption').replaceChildren();
  for (const a of state.assumptions) { const option=node('option',a.payload.proposition,$('assumption')); option.value=a.record_id; }
  if (state.assumptions.some(a=>a.record_id===selected)) $('assumption').value=selected;
  task=state.tasks.filter(t=>t.record.payload.assumption_ref.record_id===$('assumption').value).at(-1)||null;
  expectedOutlook=state.heads.outlook;
  $('model-status').textContent=state.model_available ? 'AI proposals require analyst review; citations are checked against this task.' : 'AI is not connected. Manual review is available.';
  $('history').replaceChildren();
  if (!state.history.length) node('p','No review decisions saved yet.',$('history'));
  for (const record of [...state.history].reverse()) {
    const p=record.payload, d=p.difference, box=node('div','',$('history')); box.className='history-item';
    node('h3',`${d.kind.replaceAll('_',' ')} · ${p.state}`,box);
    node('p',`${d.old_value.value} ${d.old_value.unit} → ${d.new_value.value} ${d.new_value.unit} · reviewed ${p.reviewed_at}`,box);
    node('p',d.rationale,box);
    if (d.kind==='revised') { const b=node('button','Export proposed input change',box); b.onclick=()=>run(async()=>{
      const decision=await api('/read',{ref:p.decision_ref});
      const proposal=await api('/proposals',{idempotency_key:decision.payload.idempotency_key});
      const exported=await api('/export',{ref:ref(proposal)});
      const url=URL.createObjectURL(new Blob([JSON.stringify(exported,null,2)],{type:'application/json'}));
      const a=document.createElement('a');a.href=url;a.download='proposal-only.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
      say('Exported a proposal only. Consequences remain uncomputed.');
    }); }
  }
  renderTask();
}
async function submitReview() {
  if (!pending) {
    const p=task.record.payload, disposition=$('disposition').value;
    if (!$('rationale').value.trim()) throw Error('Give a reason for this decision.');
    const value=$('value').value.trim();
    if (disposition==='revise' && !/^[+-]?\d+(?:\.\d+)?$/.test(value)) throw Error('Enter a signed decimal without commas.');
    const key=crypto.randomUUID();
    pending={request_id:key,idempotency_key:key,task_ref:ref(task.record),snapshot_digest:p.snapshot_ref.content_digest,
      expected_assumption_head:p.assumption_ref,expected_outlook_head:expectedOutlook,disposition,rationale:$('rationale').value,
      new_value:disposition==='revise'?{...p.assumption_definition.value,value}:null};
  }
  try {
    const result=await api('/reviews',pending);
    pending=null; task=null; renderTask(); $('rationale').value=''; $('receipt').textContent=`Saved review receipt: ${result.decision_ref.record_id}`;
    await refresh(); say('Review saved. The history below reflects the server record.');
  } catch(error) { if (error.status && error.status<500) pending=null; throw error; }
}
$('login-form').onsubmit=e=>{e.preventDefault();const email=$('email').value,password=$('password').value;
  run(async()=>{clearPrivate(); prefix=`/v1/tenants/${encodeURIComponent($('tenant').value)}/cases/${encodeURIComponent($('case').value)}`;
    const result=await api('/session',{email,password},true);token=result.id_token;
    $('audit').value=new Date().toISOString();await refresh();$('login').hidden=true;$('desk').hidden=false;$('signout').hidden=false;
    $('case-label').textContent=`${$('case').value} · saved local records · fictional evidence`;
    say('Connected. Prepare a review or inspect saved history.');
  });};
$('signout').onclick=()=>{clearPrivate();say('Signed out. Private case data cleared.');controls();};
$('refresh').onclick=()=>run(async()=>{await refresh();say('Saved state refreshed.');});
$('compile').onclick=()=>run(async()=>{
  const snapshot=await api('/snapshots',{audit_cutoff:$('audit').value});
  const compiled=await api('/compile',{snapshot_ref:ref(snapshot),assumption_id:$('assumption').value,information_cutoff:$('information').value});
  await refresh();task=state.tasks.find(t=>same(ref(t.record),ref(compiled)));renderTask();say('Evidence and prior assumption loaded.');
});
$('assumption').onchange=()=>{task=state.tasks.filter(t=>t.record.payload.assumption_ref.record_id===$('assumption').value).at(-1)||null;renderTask();};
$('judge').onclick=()=>run(async()=>{const result=await api('/judgments',{task_ref:ref(task.record),idempotency_key:crypto.randomUUID()});await refresh();renderJudgment(result);say('Cited brief saved as a proposal.');});
$('probe-request').onclick=()=>run(async()=>{await api('/probe-bundles',{task_ref:ref(task.record),idempotency_key:crypto.randomUUID()});await refresh();say('Probe bundle saved as a proposal.');});
$('probe-fixture-select').onchange=()=>{if(probeFixtureKey)renderProbePreview();};
$('pair-compare').onclick=()=>run(async()=>{
  const chosen=id=>pairOptions[Number($(id).value)];
  const before=chosen('pair-before'), after=chosen('pair-after');
  if (!before || !after || before===after) throw Error('Choose two different saved bundles to compare.');
  const query=`/probe-bundles/pair?before=${encodeURIComponent(JSON.stringify(ref(before.bundle)))}&after=${encodeURIComponent(JSON.stringify(ref(after.bundle)))}`;
  const box=$('pair');
  // The box is cleared only once there is an answer to show, so a failed request leaves
  // the panel's guidance in place instead of emptying it.
  try {
    const view=await api(query);
    box.replaceChildren();
    renderPairView(box,view,state);
    say('Cutoff pair derived from the two saved bundles. Nothing was saved.');
  } catch(error) {
    if (!String(error.code||'').startsWith('PAIR_')) throw error;
    box.replaceChildren();
    renderPairRefusal(box,error);
    say(`The pair was refused with ${error.code}. Nothing was saved.`);
  }
});
$('pair-fixture-select').onchange=()=>{if(pairFixtureKey)renderPairPreview();};
// Either choice must recheck Compare at once: choosing the same bundle on both sides
// disables it, and correcting the choice must enable it without another workspace action.
$('pair-before').onchange=controls;$('pair-after').onchange=controls;
$('review-form').onsubmit=e=>{e.preventDefault();run(submitReview);};
$('retry').onclick=()=>run(submitReview);
$('disposition').onchange=controls;$('value').oninput=controls;
$('close-source').onclick=()=>$('source-dialog').close();
if (probeFixtureKey) {
  const fixtures = (PROBE_FIXTURES && PROBE_FIXTURES.fixtures) || {}, keys = Object.keys(fixtures);
  if (!keys.includes(probeFixtureKey)) probeFixtureKey = keys[0] || null;
  for (const key of keys) { const option = node('option', fixtures[key].label, $('probe-fixture-select')); option.value = key; }
  if (probeFixtureKey) { $('probe-fixture-select').value = probeFixtureKey; $('probe-fixture-bar').hidden = false; renderProbePreview(); }
}
if (pairFixtureKey) {
  const fixtures = (PAIR_FIXTURES && PAIR_FIXTURES.fixtures) || {}, keys = Object.keys(fixtures);
  if (!keys.includes(pairFixtureKey)) pairFixtureKey = keys[0] || null;
  for (const key of keys) { const option = node('option', fixtures[key].label, $('pair-fixture-select')); option.value = key; }
  if (pairFixtureKey) { $('pair-fixture-select').value = pairFixtureKey; $('pair-fixture-bar').hidden = false; renderPairPreview(); }
}
controls();
